import{c as t,Q as i,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"OIDC security","description":"PKCE enforcement, key rotation, and token lifetimes.","frontmatter":{"title":"OIDC security","description":"PKCE enforcement, key rotation, and token lifetimes."},"headers":[],"relativePath":"security/oidc-security.md","filePath":"security/oidc-security.md"}'),o={name:"security/oidc-security.md"};function n(s,e,d,c,h,l){return i(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="pkce-required" tabindex="-1">PKCE required <a class="header-anchor" href="#pkce-required" aria-label="Permalink to &quot;PKCE required&quot;">​</a></h2><p>PKCE (Proof Key for Code Exchange, pronounced &quot;pixie&quot;) is a security extension to OAuth 2.0 that prevents authorization code interception. In the standard authorization code flow, an attacker who intercepts the code (for example, through a compromised redirect URI) can exchange it for tokens. PKCE prevents this by requiring the client to prove it initiated the request.</p><p>GateKeeper requires PKCE for all authorization requests. Clients that do not send a <code>code_challenge</code> parameter will receive an error.</p><h2 id="implicit-flow-disabled" tabindex="-1">Implicit flow disabled <a class="header-anchor" href="#implicit-flow-disabled" aria-label="Permalink to &quot;Implicit flow disabled&quot;">​</a></h2><p>The implicit flow returns access tokens directly in the URL fragment, making them visible in browser history and server logs. GateKeeper does not support it. Use the authorization code flow with PKCE.</p><h2 id="signing-keys" tabindex="-1">Signing keys <a class="header-anchor" href="#signing-keys" aria-label="Permalink to &quot;Signing keys&quot;">​</a></h2><p>OIDC tokens are signed with 2048-bit RSA keys using the RS256 algorithm (RSA with SHA-256). Keys rotate every 30 days. The previous key is kept active for validation until all tokens signed with it have expired.</p><p>Public keys are published at <code>/oauth/jwks</code> in JSON Web Key Set (JWKS) format. Any client can fetch this to verify token signatures without contacting GateKeeper for each request.</p><h2 id="token-lifetimes" tabindex="-1">Token lifetimes <a class="header-anchor" href="#token-lifetimes" aria-label="Permalink to &quot;Token lifetimes&quot;">​</a></h2><p>Short-lived tokens limit the window an attacker has if a token is stolen.</p><table tabindex="0"><thead><tr><th>Token</th><th>Lifetime</th></tr></thead><tbody><tr><td>Access token</td><td>15 minutes</td></tr><tr><td>Refresh token</td><td>30 days</td></tr><tr><td>ID token</td><td>15 minutes</td></tr></tbody></table><p>Refresh tokens are stored server-side. They can be revoked immediately by deleting the token record. Access tokens cannot be revoked before they expire (this is inherent to bearer tokens).</p><h2 id="client-authentication" tabindex="-1">Client authentication <a class="header-anchor" href="#client-authentication" aria-label="Permalink to &quot;Client authentication&quot;">​</a></h2><p>Confidential clients (server-side apps) must authenticate using HTTP Basic Auth with their client ID and secret on the token endpoint. Public clients are not supported.</p>',14)])])}const k=t(o,[["render",n]]);export{p as __pageData,k as default};
